        if (q !== 0) begin
            $display("Error: Expected q = 0 after wrap-around, got q = %d", q);
            errors = errors + 1;
        end

        // Final check
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
